<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, ApiError } from '../api'
import { useListBackLocation } from '../composables/listNavigation'
import type { Idea, Product } from '../types'
import { aiLabels, formatDate, linesToList, listToLines, itemPath, toast } from '../utils'
import AttachmentList from '../components/AttachmentList.vue'
import LinkManager from '../components/LinkManager.vue'
import RevisionPanel from '../components/RevisionPanel.vue'
import ConflictDialog from '../components/ConflictDialog.vue'
import ItemCreateDialog from '../components/ItemCreateDialog.vue'
import SettingLinks from '../components/SettingLinks.vue'
import CompanyCreateDialog from '../components/CompanyCreateDialog.vue'
import type { Company } from '../types'
import { useEvents } from '../events'

const backTo = useListBackLocation('/ideas')
const route = useRoute(); const router = useRouter(); const id = route.params.id as string
const idea = ref<Idea>(); const types = ref(''); const directions = ref(''); const loading = ref(true); const saving = ref(false); const error = ref(''); const dirty = ref(false); const savedPayload = ref(''); const showHistory = ref(false); const uploadBusy = ref(false); const conflict = ref<{ current: Idea; submitted: Record<string, unknown> } | null>(null); const remoteNotice = ref(false); const creatingKind = ref<'product' | 'tool'>(); const creatingCompany = ref(false)
const payload = computed(() => idea.value ? { version: idea.value.version, content: idea.value.content, display_title: idea.value.display_title, summary: idea.value.summary, notes: idea.value.notes, idea_types: linesToList(types.value), product_directions: linesToList(directions.value), } : null)
const payloadKey = (value: Record<string, unknown> | null) => JSON.stringify(Object.fromEntries(Object.entries(value || {}).filter(([key]) => key !== 'version')))
watch(payload, value => { dirty.value = payloadKey(value) !== savedPayload.value }, { deep: true })
function apply(value: Idea) { idea.value = value; types.value = listToLines(value.idea_types); directions.value = listToLines(value.product_directions); savedPayload.value = payloadKey(payload.value); dirty.value = false; remoteNotice.value = false }
async function load(force = false) { loading.value = true; error.value = ''; try { const latest = await api<Idea>(`/ideas/${id}`); if (idea.value && dirty.value && !force) remoteNotice.value = true; else apply(latest) } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
async function save() { if (!payload.value || saving.value) return; saving.value = true; error.value = ''; try { const updated = await api<Idea>(`/ideas/${id}`, { method: 'PATCH', body: JSON.stringify(payload.value) }); apply(updated); toast('已保存') } catch (e) { if (e instanceof ApiError && e.status === 409 && e.details?.current) conflict.value = { current: e.details.current, submitted: { ...payload.value, ...e.details.submitted } }; else error.value = (e as Error).message } finally { saving.value = false } }
function useServer() { if (conflict.value) apply(conflict.value.current); conflict.value = null }
async function mergeLatest() { if (!idea.value || !conflict.value) return; idea.value.version = conflict.value.current.version; conflict.value = null; await save() }
async function runAI(mode: 'normal' | 'full') { if (dirty.value) { error.value = '请先保存当前修改，再运行整理'; return }; if (mode === 'full' && !confirm('重新生成全部可整理字段会覆盖人工修改过的标题、摘要、灵感类型和商品方向。原始文字与当前正文不会改变。确认继续？')) return; try { await api(`/ideas/${id}/ai`, { method: 'POST', body: JSON.stringify({ mode }) }); if (idea.value) idea.value.ai_status = 'pending'; toast('已加入整理队列') } catch (e) { error.value = (e as Error).message } }
async function upload(images: File[]) { uploadBusy.value = true; try { for (const file of images) { const form = new FormData(); form.append('idea_id', id); form.append('file', file); const attachment = await api<any>('/attachments', { method: 'POST', body: form }); idea.value?.attachments.push(attachment) }; toast('图片已上传') } catch (e) { error.value = (e as Error).message } finally { uploadBusy.value = false } }
async function deleteAttachment(attachmentID: string) { if (!confirm('删除这张图片？')) return; await api(`/attachments/${attachmentID}`, { method: 'DELETE' }); if (idea.value) idea.value.attachments = idea.value.attachments.filter(item => item.id !== attachmentID) }
async function refreshLinks() { const latest = await api<Idea>(`/ideas/${id}`); if (idea.value && dirty.value) { idea.value.links = latest.links; idea.value.product_count = latest.product_count } else apply(latest) }
async function favorite() { if (!idea.value) return; try { const result = await api<{ favorite: boolean }>(`/ideas/${id}/favorite`, { method: 'POST', body: JSON.stringify({ favorite: !idea.value.favorite }) }); idea.value.favorite = result.favorite } catch (e) { error.value = (e as Error).message } }
async function remove() { if (!idea.value || !confirm('将这条灵感移入回收站？关联的商品不会被删除。')) return; await api(`/ideas/${id}`, { method: 'DELETE', body: JSON.stringify({ version: idea.value.version }) }); toast('已移入回收站'); router.push('/ideas') }
async function itemCreated(product: Product) { creatingKind.value = undefined; toast('已创建并关联'); await router.push(itemPath(product)) }
async function companyCreated(company: Company) { creatingCompany.value=false; try { await api('/setting-links',{method:'POST',body:JSON.stringify({idea_id:id,entity_type:'company',entity_id:company.id})});await router.push(`/companies/${company.id}`) } catch(e){error.value=(e as Error).message} }
onMounted(() => load())
useEvents(() => { if (dirty.value) remoteNotice.value = true; else load() })
</script>
<template><div v-if="loading && !idea" class="muted">读取中…</div><p v-else-if="!idea" class="error-text">{{ error }}</p><template v-else><div class="page-heading"><div><RouterLink :to="backTo">← 返回灵感库</RouterLink><h1>{{ idea.display_title || '编辑灵感' }}</h1><p>{{ idea.author_nickname }} 创建于 {{ formatDate(idea.created_at) }} · 版本 {{ idea.version }}</p></div><div class="heading-actions"><button class="secondary" :aria-label="idea.favorite ? '取消收藏' : '收藏'" @click="favorite">{{ idea.favorite ? '★ 已收藏' : '☆ 收藏' }}</button><button class="secondary" @click="showHistory = !showHistory">修改历史</button><button class="danger-button" @click="remove">移入回收站</button></div></div><p v-if="remoteNotice" class="ai-status">服务器上有新变更。保存时如发生冲突，会提供差异供你合并。</p><div class="detail-layout"><div class="detail-main"><section class="panel"><div class="ai-status" :class="{ failed: idea.ai_status === 'failed' }">{{ aiLabels[idea.ai_status] }}<span v-if="idea.ai_error"> · {{ idea.ai_error }}</span><button class="button-link" style="margin-left:.6rem" @click="runAI('normal')">{{ idea.ai_status === 'failed' ? '重试' : '重新整理' }}</button><button v-if="idea.content.trim()" class="button-link" style="margin-left:.6rem" @click="runAI('full')">重新生成全部字段</button></div><div class="field"><label for="title">展示标题</label><input id="title" v-model="idea.display_title" maxlength="160" placeholder="可以留空" /></div><div class="field"><label for="content">当前文字</label><textarea id="content" v-model="idea.content" rows="7" maxlength="200000"></textarea><small>修改文字后不会自动调用 AI，可在保存后手动重新整理。</small></div><div class="field"><label for="summary">摘要</label><textarea id="summary" v-model="idea.summary" rows="3" maxlength="4000"></textarea></div><div class="field"><label for="notes">补充备注</label><textarea id="notes" v-model="idea.notes" rows="3" maxlength="20000" placeholder="只记录额外说明，不参与自动整理"></textarea></div><div class="field-inline"><div class="field"><label for="types">灵感类型</label><input id="types" v-model="types" placeholder="名称、玩法、包装" /><small>讨论的方面，如名称、商品概念、玩法、包装、世界观。用逗号分隔，可留空。</small></div><div class="field"><label for="directions">商品方向</label><input id="directions" v-model="directions" placeholder="饮料、零食" /><small>明确的商品品类，如饮料、乳制品、零食、日用品。不确定时留空。</small></div></div><p v-if="error" class="error-text">{{ error }}</p><div class="form-actions"><button class="primary" :disabled="saving || !dirty" @click="save">{{ saving ? '保存中…' : dirty ? '保存修改' : '已保存' }}</button><span v-if="dirty" class="muted">有未保存修改</span><button class="secondary push-right" @click="creatingKind = 'product'">由此灵感创建商品</button><button class="secondary" @click="creatingKind = 'tool'">由此灵感创建道具</button><button class="secondary" @click="creatingCompany = true">由此灵感创建公司</button></div></section><section class="panel"><h2>附件</h2><AttachmentList :items="idea.attachments" :busy="uploadBusy" @upload="upload" @delete="deleteAttachment" /></section><details class="panel"><summary>首次提交的原始内容（永久保留）</summary><p class="original-content" style="margin-top:1rem">{{ idea.original_content || '（纯图片投稿，无文字）' }}</p></details><RevisionPanel v-if="showHistory" kind="idea" :id="id" :version="idea.version" @restored="load(true)" /></div><aside class="side-panel"><section class="panel"><h2>关联商品与道具</h2><LinkManager owner-type="idea" :owner-id="id" :links="idea.links || []" @changed="refreshLinks" /></section><section class="panel"><h2>关联公司与配方</h2><SettingLinks kind="idea" :id="id" /></section></aside></div></template>
  <ConflictDialog v-if="conflict" :current="conflict.current" :submitted="conflict.submitted" @server="useServer" @merge="mergeLatest" @cancel="conflict = null" />
  <ItemCreateDialog v-if="creatingKind" :kind="creatingKind" :idea-id="id" :initial-name="idea?.display_title || idea?.content.slice(0,80)" :initial-description="idea?.content" @created="itemCreated" @cancel="creatingKind = undefined" />
  <CompanyCreateDialog v-if="creatingCompany" :initial-name="idea?.display_title" @created="companyCreated" @cancel="creatingCompany = false" />
</template>
